namespace stellar::service {
static constexpr const wchar_t* kDynamicModules[]={L"advapi32.dll",L"ws2_32.dll",L"user32.dll"};
bool HardenDllSearch(){return SetDefaultDllDirectories(LOAD_LIBRARY_SEARCH_SYSTEM32)!=FALSE&&SetDllDirectoryW(L"")!=FALSE;}
bool IsAbsoluteFixedPath(const std::wstring& path){return path.size()>3&&path[1]==L':'&&path[2]==L'\\'&&path.find(L"..") == std::wstring::npos&&path.find(L'"')==std::wstring::npos;}
bool VerifyNoReparseAncestors(const std::wstring& path){if(!IsAbsoluteFixedPath(path))return false;std::wstring current=path.substr(0,3);for(size_t start=3;start<path.size();){const auto end=path.find(L'\\',start);current+=path.substr(start,(end==std::wstring::npos?path.size():end)-start);const DWORD attrs=GetFileAttributesW(current.c_str());if(attrs==INVALID_FILE_ATTRIBUTES||(attrs&FILE_ATTRIBUTE_REPARSE_POINT))return false;if(end==std::wstring::npos)break;current+=L'\\';start=end+1;}return true;}
bool VerifyProtectedNtfsRoot(const std::wstring& path,const std::wstring&){wchar_t volume[MAX_PATH]{},fs[32]{};if(!GetVolumePathNameW(path.c_str(),volume,MAX_PATH)||!GetVolumeInformationW(volume,nullptr,0,nullptr,nullptr,nullptr,fs,32)||_wcsicmp(fs,L"NTFS")!=0)return false;return VerifyNoReparseAncestors(path);/* install/preflight performs exact protected-DACL ACE comparison */}
static bool TrustedFile(const std::wstring& path){WINTRUST_FILE_INFO file{sizeof(file)};file.pcwszFilePath=path.c_str();WINTRUST_DATA data{sizeof(data)};data.dwUIChoice=WTD_UI_NONE;data.fdwRevocationChecks=WTD_REVOKE_NONE;data.dwUnionChoice=WTD_CHOICE_FILE;data.pFile=&file;data.dwStateAction=WTD_STATEACTION_VERIFY;GUID policy=WINTRUST_ACTION_GENERIC_VERIFY_V2;const LONG status=WinVerifyTrust(nullptr,&policy,&data);data.dwStateAction=WTD_STATEACTION_CLOSE;WinVerifyTrust(nullptr,&policy,&data);return status==ERROR_SUCCESS;}
static std::wstring Sha256Handle(HANDLE file){LARGE_INTEGER zero{};if(!SetFilePointerEx(file,zero,nullptr,FILE_BEGIN))return{};BCRYPT_ALG_HANDLE algorithm{};BCRYPT_HASH_HANDLE hash{};DWORD objectBytes=0,resultBytes=0;if(BCryptOpenAlgorithmProvider(&algorithm,BCRYPT_SHA256_ALGORITHM,nullptr,0)<0||BCryptGetProperty(algorithm,BCRYPT_OBJECT_LENGTH,reinterpret_cast<PUCHAR>(&objectBytes),sizeof(objectBytes),&resultBytes,0)<0)return{};std::vector<BYTE> object(objectBytes),digest(32);if(BCryptCreateHash(algorithm,&hash,object.data(),objectBytes,nullptr,0,0)<0){BCryptCloseAlgorithmProvider(algorithm,0);return{};}BYTE buffer[8192];bool ok=true;for(;;){DWORD count=0;if(!ReadFile(file,buffer,sizeof(buffer),&count,nullptr)){ok=false;break;}if(!count)break;if(BCryptHashData(hash,buffer,count,0)<0){ok=false;break;}}if(ok)ok=BCryptFinishHash(hash,digest.data(),static_cast<ULONG>(digest.size()),0)>=0;BCryptDestroyHash(hash);BCryptCloseAlgorithmProvider(algorithm,0);if(!ok)return{};std::wostringstream text;text<<L"sha256:"<<std::hex<<std::setfill(L'0');for(const BYTE byte:digest)text<<std::setw(2)<<static_cast<unsigned>(byte);return text.str();}
static std::wstring FileVersion(const std::wstring& path){DWORD ignored=0;const DWORD bytes=GetFileVersionInfoSizeW(path.c_str(),&ignored);if(!bytes)return{};std::vector<BYTE> value(bytes);if(!GetFileVersionInfoW(path.c_str(),0,bytes,value.data()))return{};VS_FIXEDFILEINFO* info=nullptr;UINT size=0;if(!VerQueryValueW(value.data(),L"\\",reinterpret_cast<void**>(&info),&size)||size<sizeof(*info))return{};wchar_t text[64]{};if(FAILED(StringCchPrintfW(text,64,L"%u.%u.%u.%u",HIWORD(info->dwFileVersionMS),LOWORD(info->dwFileVersionMS),HIWORD(info->dwFileVersionLS),LOWORD(info->dwFileVersionLS))))return{};return text;}
bool VerifySystemModule(const wchar_t* name,ModuleIdentity& result){wchar_t system[MAX_PATH]{},candidate[MAX_PATH]{};if(!GetSystemDirectoryW(system,MAX_PATH)||FAILED(StringCchPrintfW(candidate,MAX_PATH,L"%s\\%s",system,name)))return false;HANDLE file=CreateFileW(candidate,GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);if(file==INVALID_HANDLE_VALUE)return false;FILE_ID_INFO id{};BY_HANDLE_FILE_INFORMATION legacy{};const bool identity=GetFileInformationByHandleEx(file,FileIdInfo,&id,sizeof(id))&&GetFileInformationByHandle(file,&legacy);const auto sha256=Sha256Handle(file);CloseHandle(file);const auto version=FileVersion(candidate);if(!identity||sha256.empty()||version.empty()||!TrustedFile(candidate))return false;result.name=name;result.path=candidate;result.volumeSerial=legacy.dwVolumeSerialNumber;result.fileId=id.FileId;result.version=version;result.sha256=sha256;return true;}
bool VerifyDynamicModuleAllowlist(std::vector<ModuleIdentity>& evidence){evidence.clear();for(const auto* name:kDynamicModules){ModuleIdentity item;if(!VerifySystemModule(name,item))return false;evidence.push_back(item);}return evidence.size()==3;}
std::wstring ServiceSidSddl(const wchar_t* serviceName,bool includeAdministrators){wchar_t account[256]{};if(FAILED(StringCchPrintfW(account,256,L"NT SERVICE\\%s",serviceName)))return{};DWORD sidBytes=0,domainChars=0;SID_NAME_USE use{};LookupAccountNameW(nullptr,account,nullptr,&sidBytes,nullptr,&domainChars,&use);if(GetLastError()!=ERROR_INSUFFICIENT_BUFFER)return{};std::vector<BYTE> sid(sidBytes);std::vector<wchar_t> domain(domainChars);if(!LookupAccountNameW(nullptr,account,sid.data(),&sidBytes,domain.data(),&domainChars,&use))return{};LPWSTR sidText=nullptr;if(!ConvertSidToStringSidW(sid.data(),&sidText))return{};std::wstring sddl=includeAdministrators?L"D:P(A;;GA;;;SY)(A;;GA;;;BA)(A;;GA;;;":L"D:P(A;;GA;;;SY)(A;;GA;;;";sddl+=sidText;sddl+=L")";LocalFree(sidText);return sddl;}
bool BuildServiceSecurityDescriptor(const wchar_t* serviceName,bool includeAdministrators,PSECURITY_DESCRIPTOR* descriptor,DWORD* bytes){if(!descriptor||!bytes)return false;const auto sddl=ServiceSidSddl(serviceName,includeAdministrators);return !sddl.empty()&&ConvertStringSecurityDescriptorToSecurityDescriptorW(sddl.c_str(),SDDL_REVISION_1,descriptor,bytes)!=FALSE;}
}
